import{c as i,Q as r,j as o,m as t}from"./chunks/framework.DOi4mjdC.js";const g=JSON.parse('{"title":"诗经","description":"","frontmatter":{"id":"shijing","title":"诗经","author":"佚名","dynasty":"先秦","cover":"/covers/shijing.jpg","sort":3,"literaryValue":"《诗经》是中国最早的诗歌总集，收录了西周初年至春秋中叶的诗歌305篇，分为风、雅、颂三部分，是中国文学史上第一部诗歌总集。"},"headers":[],"relativePath":"books/shici/shijing.md","filePath":"books/shici/shijing.md"}'),e={name:"books/shici/shijing.md"};function s(h,a,p,n,l,d){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="诗经" tabindex="-1">诗经 <a class="header-anchor" href="#诗经" aria-label="Permalink to &quot;诗经&quot;">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>《诗经》是中国古代诗歌开端，最早的一部诗歌总集，收集了西周初年至春秋中叶（前11世纪至前6世纪）的诗歌，共311篇，其中6篇为笙诗，即只有标题，没有内容，称为笙诗六篇（《南陔》《白华》《华黍》《由庚》《崇丘》《由仪》），反映了周初至周晚期约五百年间的社会面貌。</p><p>《诗经》的作者佚名，绝大部分已经无法考证，传为尹吉甫采集、孔子编订。《诗经》在先秦时期称为《诗》，或取其整数称《诗三百》。西汉时被尊为儒家经典，始称《诗经》，并沿用至今。诗经在内容上分为《风》《雅》《颂》三个部分。《风》是周代各地的歌谣；《雅》是周人的正声雅乐，又分《小雅》和《大雅》；《颂》是周王庭和贵族宗庙祭祀的乐歌，又分为《周颂》《鲁颂》和《商颂》。</p><h2 id="国风·周南" tabindex="-1">国风·周南 <a class="header-anchor" href="#国风·周南" aria-label="Permalink to &quot;国风·周南&quot;">​</a></h2><h3 id="关雎" tabindex="-1">关雎 <a class="header-anchor" href="#关雎" aria-label="Permalink to &quot;关雎&quot;">​</a></h3><p><strong><a href="/books/shici/shijing/1.html">查看详情</a></strong></p><p>关关雎鸠，在河之洲。 窈窕淑女，君子好逑。</p><p>参差荇菜，左右流之。 窈窕淑女，寤寐求之。</p><p>求之不得，寤寐思服。 悠哉悠哉，辗转反侧。</p><p>参差荇菜，左右采之。 窈窕淑女，琴瑟友之。</p><p>参差荇菜，左右芼之。 窈窕淑女，钟鼓乐之。</p><h3 id="桃夭" tabindex="-1">桃夭 <a class="header-anchor" href="#桃夭" aria-label="Permalink to &quot;桃夭&quot;">​</a></h3><p><strong><a href="/books/shici/shijing/2.html">查看详情</a></strong></p><p>桃之夭夭，灼灼其华。 之子于归，宜其室家。</p><p>桃之夭夭，有蕡其实。 之子于归，宜其家室。</p><p>桃之夭夭，其叶蓁蓁。 之子于归，宜其家人。</p><h3 id="芣苢" tabindex="-1">芣苢 <a class="header-anchor" href="#芣苢" aria-label="Permalink to &quot;芣苢&quot;">​</a></h3><p><strong><a href="/books/shici/shijing/3.html">查看详情</a></strong></p><p>采采芣苢，薄言采之。 采采芣苢，薄言有之。</p><p>采采芣苢，薄言掇之。 采采芣苢，薄言捋之。</p><p>采采芣苢，薄言袺之。 采采芣苢，薄言襭之。</p><h2 id="国风·秦风" tabindex="-1">国风·秦风 <a class="header-anchor" href="#国风·秦风" aria-label="Permalink to &quot;国风·秦风&quot;">​</a></h2><h3 id="蒹葭" tabindex="-1">蒹葭 <a class="header-anchor" href="#蒹葭" aria-label="Permalink to &quot;蒹葭&quot;">​</a></h3><p><strong><a href="/books/shici/shijing/4.html">查看详情</a></strong></p><p>蒹葭苍苍，白露为霜。 所谓伊人，在水一方。</p><p>溯洄从之，道阻且长。 溯游从之，宛在水中央。</p><p>蒹葭萋萋，白露未晞。 所谓伊人，在水之湄。</p><p>溯洄从之，道阻且跻。 溯游从之，宛在水中坻。</p><p>蒹葭采采，白露未已。 所谓伊人，在水之涘。</p><p>溯洄从之，道阻且右。 溯游从之，宛在水中沚。</p><h3 id="无衣" tabindex="-1">无衣 <a class="header-anchor" href="#无衣" aria-label="Permalink to &quot;无衣&quot;">​</a></h3><p><strong><a href="/books/shici/shijing/5.html">查看详情</a></strong></p><p>岂曰无衣？与子同袍。 王于兴师，修我戈矛。与子同仇！</p><p>岂曰无衣？与子同泽。 王于兴师，修我矛戟。与子偕作！</p><p>岂曰无衣？与子同裳。 王于兴师，修我甲兵。与子偕行！</p><h2 id="小雅" tabindex="-1">小雅 <a class="header-anchor" href="#小雅" aria-label="Permalink to &quot;小雅&quot;">​</a></h2><h3 id="鹿鸣" tabindex="-1">鹿鸣 <a class="header-anchor" href="#鹿鸣" aria-label="Permalink to &quot;鹿鸣&quot;">​</a></h3><p><strong><a href="/books/shici/shijing/6.html">查看详情</a></strong></p><p>呦呦鹿鸣，食野之苹。 我有嘉宾，鼓瑟吹笙。</p><p>吹笙鼓簧，承筐是将。 人之好我，示我周行。</p><p>呦呦鹿鸣，食野之蒿。 我有嘉宾，德音孔昭。</p><p>视民不恌，君子是则是效。 我有旨酒，嘉宾式燕以敖。</p><p>呦呦鹿鸣，食野之芩。 我有嘉宾，鼓瑟鼓琴。</p><p>鼓瑟鼓琴，和乐且湛。 我有旨酒，以燕乐嘉宾之心。</p><h3 id="采薇" tabindex="-1">采薇 <a class="header-anchor" href="#采薇" aria-label="Permalink to &quot;采薇&quot;">​</a></h3><p><strong><a href="/books/shici/shijing/1.html">查看详情</a></strong></p><p>采薇采薇，薇亦作止。 曰归曰归，岁亦莫止。</p><p>靡室靡家，猃狁之故。 不遑启居，猃狁之故。</p><p>采薇采薇，薇亦柔止。 曰归曰归，心亦忧止。</p><p>忧心烈烈，载饥载渴。 我戍未定，靡使归聘。</p><p>采薇采薇，薇亦刚止。 曰归曰归，岁亦阳止。</p><p>王事靡盬，不遑启处。 忧心孔疚，我行不来！</p><p>彼尔维何？维常之华。 彼路斯何？君子之车。</p><p>戎车既驾，四牡业业。 岂敢定居？一月三捷。</p><p>驾彼四牡，四牡骙骙。 君子所依，小人所腓。</p><p>四牡翼翼，象弭鱼服。 岂不日戒？猃狁孔棘！</p><p>昔我往矣，杨柳依依。 今我来思，雨雪霏霏。</p><p>行道迟迟，载渴载饥。 我心伤悲，莫知我哀！</p><h2 id="艺术特色" tabindex="-1">艺术特色 <a class="header-anchor" href="#艺术特色" aria-label="Permalink to &quot;艺术特色&quot;">​</a></h2><p>《诗经》的艺术特色主要体现在以下几个方面：</p><ol><li><strong>赋比兴手法</strong>：赋是直陈其事，比是比喻，兴是托物起兴，这三种手法奠定了中国诗歌创作的基础</li><li><strong>重章叠句</strong>：各章句式重复，只更换少数词语，形成回环往复的音乐美</li><li><strong>四言为主</strong>：以四字句为主，节奏鲜明，朗朗上口</li><li><strong>现实主义精神</strong>：真实反映社会生活，关注人民疾苦</li></ol><h2 id="影响与价值" tabindex="-1">影响与价值 <a class="header-anchor" href="#影响与价值" aria-label="Permalink to &quot;影响与价值&quot;">​</a></h2><p>《诗经》是中国文学的光辉起点，对后世文学产生了深远影响：</p><ul><li><strong>文学传统</strong>：开创了中国诗歌的现实主义传统</li><li><strong>艺术手法</strong>：赋比兴成为中国诗歌的基本表现手法</li><li><strong>语言典范</strong>：许多诗句成为后世常用的成语典故</li><li><strong>文化价值</strong>：是研究先秦社会历史的重要资料</li></ul>',65)])])}const b=i(e,[["render",s]]);export{g as __pageData,b as default};
